Qed.

Lemma lapi_0RB____0LC1RD_1RB1LC_0LD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
