Lemma geo_0RB____0LC1RD_1RB1LC_0LD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB____0LC1RD_1RB1LC_0LD0RB) = lift (Cc (Pos.succ p)).
