  - exists (4 * j + 7), (cden [] [] j BB1_0RB____0LC1RD_1RB1LC_0LD0RB).
    split; [lia|]. split; [| exact (gbo_0RB____0LC1RD_1RB1LC_0LD0RB j)].
    rewrite (gso_0RB____0LC1RD_1RB1LC_0LD0RB p j E).
    exact (srun_sound tm true true chb_0RB____0LC1RD_1RB1LC_0LD0RB B0_0RB____0LC1RD_1RB1LC_0LD0RB BB1_0RB____0LC1RD_1RB1LC_0LD0RB 4 7
             run_boot_0RB____0LC1RD_1RB1LC_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 13), (cden [] [] j B1_0RB____0LC1RD_1RB1LC_0LD0RB).
    split; [| exact (geo_0RB____0LC1RD_1RB1LC_0LD0RB p j E)].
    rewrite (gxi_0RB____0LC1RD_1RB1LC_0LD0RB j).
    exact (srun_sound tm true true che_0RB____0LC1RD_1RB1LC_0LD0RB BE0_0RB____0LC1RD_1RB1LC_0LD0RB B1_0RB____0LC1RD_1RB1LC_0LD0RB 4 13
             run_exit_0RB____0LC1RD_1RB1LC_0LD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB____0LC1RD_1RB1LC_0LD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB____0LC1RD_1RB1LC_0LD0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB____0LC1RD_1RB1LC_0LD0RB p j' E).
Qed.

